}
func values(n *yamlv3.Node) []*yamlv3.Node {
 if n==nil || n.Kind!=yamlv3.SequenceNode { return nil }; return n.Content
}
func value(n *yamlv3.Node) string { if n==nil { return "" }; return n.Value }
func referenceErrors(file string, root *yamlv3.Node) []error {
 namespace:=value(field(root,"namespace")); if namespace=="" { namespace="default" }
 segments:=map[string]bool{}
 for _, s:=range values(field(root,"segments")) { segments[value(field(s,"key"))]=true }
 var issues []error
