  if n==nil || n.Value=="" { return }
  issues=append(issues, Error{Message:fmt.Sprintf("flag %s/%s rule %d references unknown %s %q", namespace,flag,index,kind,n.Value), Location:Location{File:file,Line:n.Line,Column:n.Column}})
